#!/usr/bin/env bun
import { add, load, markDone, save } from "./store";

const [cmd, ...rest] = process.argv.slice(2);
const todos = load();

switch (cmd) {
	case "add": {
		const text = rest.join(" ").trim();
		if (!text) {
			console.error("usage: todo add <text>");
			process.exit(1);
		}
		const t = add(todos, text);
		save(todos);
		console.log(`added ${t.id}`);
		break;
	}
	case "done": {
		const id = Number(rest[0]);
		const t = markDone(todos, id);
		if (!t) {
			console.error(`unknown todo id: ${rest[0] ?? ""}`);
			process.exit(1);
		}
		save(todos);
		console.log(`done ${t.id}`);
		break;
	}
	case "list":
		for (const t of todos) console.log(`${t.done ? "[x]" : "[ ]"} ${t.id}  ${t.text}`);
		break;
	default:
		console.error("usage: todo <add|list|done> ...");
		process.exit(1);
}

